/**
 * n8n Function
 * Toma cada item con `json.query` (string JSON, objeto o array) y
 * emite 1 item por registro con:
 *   - JSON: el objeto original (stringificado)
 *   - nombre: etiqueta útil "<CasoID>-<OPERACION>-<Tabla>"
 *
 * Soporta el ejemplo:
 * [
 *   {
 *     "query": "[{...}]"
 *   }
 * ]
 */

function parseQuery(q) {
  if (q == null) return [];
  // Si ya viene como objeto/array -> normalizar a array
  if (Array.isArray(q)) return q;
  if (typeof q === 'object') return [q];

  // Si viene como string -> intentar parsear
  if (typeof q === 'string') {
    const s = q.trim();
    try {
      const parsed = JSON.parse(s);
      if (Array.isArray(parsed)) return parsed;
      if (typeof parsed === 'object' && parsed) return [parsed];
    } catch (e) {
      // Intento de parseo "relajado": quitar saltos iniciales, comas colgantes típicas
      const relaxed = s
        .replace(/,\s*]/g, ']')
        .replace(/,\s*}/g, '}');
      try {
        const parsed2 = JSON.parse(relaxed);
        if (Array.isArray(parsed2)) return parsed2;
        if (typeof parsed2 === 'object' && parsed2) return [parsed2];
      } catch { /* caerá a vacío */ }
    }
  }
  return [];
}

function toStringSafe(obj) {
  if (typeof obj === 'string') return obj;
  try { return JSON.stringify(obj); } catch { return String(obj); }
}

const out = [];

for (const item of items) {
  const lista = parseQuery(item.json?.query);

  for (const e of lista) {
    // Normalizaciones mínimas
    const CasoID            = (e?.CasoID ?? '').toString().trim();
    const NombreCliente     = (e?.NombreCliente ?? '').toString().trim();
    const NombreBaseDeDatos = (e?.NombreBaseDeDatos ?? '').toString().trim();
    const NombreDeLaTabla   = (e?.NombreDeLaTabla ?? '').toString().trim();
    const Operacion         = (e?.Operacion ?? '').toString().trim().toUpperCase();
    const QueryDeOperacion  = (e?.QueryDeOperacion ?? '').toString().trim();
    const QueryParaBackup   = (e?.QueryParaBackup ?? '').toString().trim();
    const ResultadoDeOperacion = e?.ResultadoDeOperacion ?? '';
    const ResultadoBackup      = e?.ResultadoBackup ?? '';

    // Ensamblar objeto limpio
    const registro = {
      CasoID,
      NombreCliente,
      NombreBaseDeDatos,
      NombreDeLaTabla,
      Operacion,
      QueryDeOperacion,
      QueryParaBackup,
      ResultadoDeOperacion,
      ResultadoBackup
    };

    // Etiqueta "nombre": <ID>-<OP>-<TABLA>
    const nombre = [
      CasoID || 'SINID',
      Operacion || 'OP',
      NombreDeLaTabla || 'SINTABLA'
    ].join('-');

    out.push({
      json: {
        JSON: toStringSafe(registro),
        nombre
      }
    });
  }
}

return out;
